const MON = ["января","февраля","марта","апреля","мая","июня","июля","августа","сентября","октября","ноября","декабря"];
function fd(iso){ if(!iso) return ""; const [y,m,d]=iso.split("-"); return d+"."+m+"."+y; }
function fdl(iso){ if(!iso) return ""; const [y,m,d]=iso.split("-"); return "«"+d+"» "+MON[+m-1]+" "+y+" г."; }
function fdw(iso){ if(!iso) return ""; const [y,m,d]=iso.split("-"); return (+d)+" "+MON[+m-1]+" "+y+" г."; }
function initials(fio){ const p=(fio||"").trim().split(/\s+/); if(!p[0]) return ""; return p[0]+(p[1]?" "+p[1][0]+".":"")+(p[2]?" "+p[2][0]+".":""); }
const isIP = s => /^(ИП|Индивидуальный)/i.test(s.name||"");

/* сумма прописью */
const O_M=["","один","два","три","четыре","пять","шесть","семь","восемь","девять"], O_F=["","одна","две","три","четыре","пять","шесть","семь","восемь","девять"];
const TEEN=["десять","одиннадцать","двенадцать","тринадцать","четырнадцать","пятнадцать","шестнадцать","семнадцать","восемнадцать","девятнадцать"];
const TENS=["","","двадцать","тридцать","сорок","пятьдесят","шестьдесят","семьдесят","восемьдесят","девяносто"];
const HUN=["","сто","двести","триста","четыреста","пятьсот","шестьсот","семьсот","восемьсот","девятьсот"];
function plural(n,f){ n=Math.abs(n)%100; const a=n%10; if(n>10&&n<20) return f[2]; if(a>1&&a<5) return f[1]; if(a===1) return f[0]; return f[2]; }
function tri(n,fem){ const t=n%100, r=[HUN[Math.floor(n/100)]]; if(t>=10&&t<20) r.push(TEEN[t-10]); else { r.push(TENS[Math.floor(t/10)]); r.push((fem?O_F:O_M)[t%10]); } return r.filter(Boolean).join(" "); }
function intWords(n,fem){
  if(n===0) return "ноль";
  const G=[[null,fem],[["тысяча","тысячи","тысяч"],true],[["миллион","миллиона","миллионов"],false],[["миллиард","миллиарда","миллиардов"],false]];
  const out=[]; let i=0;
  while(n>0 && i<G.length){ const g=n%1000; if(g){ let w=tri(g,G[i][1]); if(G[i][0]) w+=" "+plural(g,G[i][0]); out.unshift(w); } n=Math.floor(n/1000); i++; }
  return out.join(" ");
}
const cap = s => s ? s[0].toUpperCase()+s.slice(1) : s;
function moneyWords(x){ const c=Math.round(x*100), r=Math.floor(c/100), k=c%100;
  return cap(intWords(r,false)+" "+plural(r,["рубль","рубля","рублей"])+" "+String(k).padStart(2,"0")+" "+plural(k,["копейка","копейки","копеек"])); }


const req = (o) => [o.name, o.inn&&("ИНН "+o.inn), o.kpp&&("КПП "+o.kpp), o.address, o.phone&&("тел.: "+o.phone)].filter(Boolean).join(", ");
const num = v => String(v).replace(/\s/g,"").replace(",",".");
const addrs = c => String(c.ship||"").split(/\n/).map(x=>x.trim()).filter(Boolean);
const firstAddr = c => addrs(c)[0] || "";
const ctrs = cid => (D.contracts||[]).filter(x=>x.customerId===cid);
const ctr = id => id ? (D.contracts||[]).find(x=>x.id===id) : null;
const ctrLabel = x => (x.basis||"(без номера)")+" — "+(x.supplierId ? (sup(x.supplierId).name||"исполнитель удалён") : "любой исполнитель");
const isArch = j => !!(j && j.snap && j.snap.meta && j.snap.meta.arch);
/* нумерация: своя у каждой пары «поставщик + заказчик» */
const numsOf = c => { try{ const o=JSON.parse((c&&c.nums)||"{}"); return o&&typeof o==="object"?o:{}; }catch(e){ return {}; } };
const pairDocs = (sid, cid, except) => D.journal.filter(j=>!isArch(j) && j.supplierId===sid && j.customerId===cid && j.id!==except);
function pairLast(sid, cid, except){ let best=null; pairDocs(sid,cid,except).forEach(j=>{ const n=parseInt(j.number,10)||0; if(!best || n>best.n || (n===best.n && j.date>best.j.date)) best={n, j}; }); return best; }
function nextNum(sid, cid, skip, except){
  const last=pairLast(sid,cid,except), st=parseInt(numsOf(cus(cid))[sid],10)||0;
  let n=Math.max(last?last.n+1:1, st||1); const used=new Set(pairDocs(sid,cid,except).map(j=>String(j.number))); (skip||[]).forEach(x=>used.add(String(x)));
  while(used.has(String(n))) n++; return String(n); }
/* документы этой пары «поставщик + заказчик» с таким же номером (кроме архива и самого документа) */
const numTaken = (sid, cid, num, except) => { const n=String(num||"").trim(); return n ? pairDocs(sid,cid,except).filter(j=>String(j.number).trim()===n) : []; };
const numWho = j => { const w=j.snap&&j.snap.c ? String(j.snap.c.branchLabel||stLabel((j.snap.dr||{}).ship||"", j.snap.c.address)||"").trim() : ""; return "№ "+j.number+" от "+fd(j.date)+(w?" ("+w+")":""); };
/* «Новый документ»: номер уже есть у этого заказчика → поле красное, подпись-предупреждение; сохранить можно */
function numMark(){ const dr=D.draft, el=$("#d-num"), info=$("#d-numinfo"); if(!dr||!el||!info) return;
  const t=dr.qtyOnly?[]:numTaken(dr.supplierId, dr.customerId, dr.number, dr.id); el.classList.toggle("numdup", !!t.length); info.classList.toggle("numdup", !!t.length);
  if(t.length){ info.classList.remove("warn"); info.textContent="Внимание: у этого заказчика уже есть "+t.map(numWho).join("; ")+". Сохранить можно, но номер задвоится."; } }
const ctrUsed = (id, except) => r2(D.journal.filter(j=>j.snap && !isArch(j) && j.snap.dr.contractId===id && j.id!==except).reduce((a,j)=>a+(+j.sum||0),0));

/* ---------- расчёт (по текущим справочникам или по снимку из журнала) ---------- */
function calc(dr, snap){
  const s = snap ? snap.s : sup(dr.supplierId), c = snap ? snap.c : liveCus(dr);
  const P = id => snap ? (snap.prods||{})[id] : prod(id);
  /* НДС: настройка заказчика («10+» — 10% сверху цены прайса, «10» — уже в цене) важнее настройки поставщика */
  const cv = String((c && c.vat) || (!snap && (cus(dr.customerId)||{}).vat) || ""), cm = cv.match(/^(\d+)(\+?)$/);
  const rate = cm ? +cm[1] : (s.vat==="none"||!s.vat ? null : +s.vat), add = !!(cm && cm[2]);
  const t12 = !!c && (c.t12c==="1" || (cus(dr.customerId)||{}).t12c==="1");
  const lines = dr.lines.filter(l=>l.productId && +l.qty>0).map((l,i)=>{
    const p=P(l.productId)||{}; const qty=+l.qty, price=+l.price||0;
    let sum, vat, net, gp=price;
    if(add){ net=r2(qty*price); vat=r2(net*rate/100); sum=r2(net+vat); gp=r2(price*(100+rate)/100); }
    else { sum=r2(qty*price); vat=rate?r2(sum*rate/(100+rate)):0; net=r2(sum-vat); }
    const cty=p.country||(snap?(prod(l.productId)||{}).country:"")||"";
    const nm=(l.name&&String(l.name).trim())||p.name||"";
    return {n:i+1, pid:l.productId, lid:l.lid||"", stk:l.stk||null, code:p.code||"", name:nm, unit:p.unit||"", okei:UNITS[p.unit]||"", country:cty, nameT:(t12&&COUNTRIES[cty])?nm+", страна происхождения — "+COUNTRIES[cty]:"", qty, price:gp, sum, vat, net, priceNet: add ? price : rate? r2(net/qty) : price};
  });
  const t = lines.reduce((a,l)=>({sum:a.sum+l.sum, vat:a.vat+l.vat, net:a.net+l.net, qty:a.qty+l.qty, kg:a.kg+(l.unit==="кг"?l.qty:0)}),{sum:0,vat:0,net:0,qty:0,kg:0});
  ["sum","vat","net"].forEach(x=>t[x]=r2(t[x]));
  return {s, c, rate, add, lines, t, dr, t12};
}
const branches = c => { try{ const a=JSON.parse(c.branches||"[]"); return Array.isArray(a)?a:[]; }catch(e){ return []; } };
/* «Частное лицо» — покупатель без реквизитов: простая накладная без ИНН, банка и договора */
const PRIV_ID="private-buyer", isPriv = id => id===PRIV_ID;
function patchPrivate(){ if(D.customers.some(c=>c.id===PRIV_ID)) return; D.customers.push({id:PRIV_ID, name:"Частное лицо", inn:"", kpp:"", address:"", ship:"", acct:"bank", bank:"", bik:"", rs:"", ks:""}); dirty("customers", PRIV_ID); }
function liveCus(dr){
  const c=cus(dr.customerId), x=ctr(dr.contractId), b=branches(c).find(y=>y.id===dr.branchId), o=Object.assign({}, c, {ikz: x ? (x.ikz||"") : ""});
  if(b){ ["kpp","address","acct","bank","bik","rs","ks","ship","edo"].forEach(k=>{ if(b[k]) o[k]=b[k]; }); if(b.fullName) o.name=b.fullName; o.branchLabel=b.label||""; }
  if(isPriv(dr.customerId)){ o.priv=1; o.name=String(dr.buyer||"").trim()||"Частное лицо"; o.phone=String(dr.bphone||"").trim(); o.address=dr.ship||""; o.inn=""; o.kpp=""; o.bank=o.bik=o.rs=o.ks=""; }
  return o;
}
function makeSnap(dr){
  dr.lines.forEach(l=>{ if(l.productId && !l.lid) l.lid=uid()+uid(); });   /* постоянный id строки: по нему склад связывает резерв и отгрузку */
  const prods={}; dr.lines.forEach(l=>{ const p=prod(l.productId); if(p) prods[p.id]={name:p.name, code:p.code, unit:p.unit, country:p.country}; });
  const s=clone(sup(dr.supplierId)); delete s.stamp; delete s.sign;
  const saved=clone(dr); delete saved._editBase; return {dr:saved, s, c:clone(liveCus(dr)), prods};
}

/* ================= синхронизация с Google Таблицей ================= */
const pass = () => { try{ return localStorage.getItem(PKEY)||""; }catch(e){ return ""; } };
const lsGet = k => { try{ return localStorage.getItem(k)||""; }catch(e){ return ""; } }, lsSet = (k,v) => { try{ v==null?localStorage.removeItem(k):localStorage.setItem(k,v); }catch(e){} };
const curUser = () => lsGet(UKEY);
const me = () => { try{ return JSON.parse(lsGet(MKEY)||"null")||{}; }catch(e){ return {}; } };
const role = () => { const m=me(); return m.role || (m.admin ? "admin" : "manager"); };
const isStaff = () => role()==="staff";
/* сотрудник склада с правом полностью редактировать документы (в «Пароли.gs»: docs:true) — в документах как менеджер */
const docLimited = () => isStaff() && !me().docs;
const STAFF_HIDE = ["invoices","archive","customers","products","suppliers","data","profit","purchase","events","tasks"];
const ADMIN_TABS = ["events","profit","purchase","tasks"];
if(pass() && !curUser()){ lsSet(UKEY,"Даниил"); lsSet(MKEY, JSON.stringify({name:"Даниил", admin:true})); }   /* вход, сохранённый до появления пользователей */
/* журнал событий: очередь отправки (переживает перезагрузку и отсутствие связи) */
let evq=[]; try{ evq=JSON.parse(lsGet(EKEY)||"[]")||[]; }catch(e){ evq=[]; }
function logEv(action, text, docId){ if(!curUser()) return; evq.push({at:new Date().toISOString(), action, text, docId:docId||""}); evq=evq.slice(-300); lsSet(EKEY, JSON.stringify(evq)); changed(); }
const jDesc = j => "№ "+j.number+" от "+fd(j.date)+" — "+shortCus(calc(j.snap.dr, j.snap));
function deviceName(){ const u=navigator.userAgent||""; return /Android/i.test(u)?"Android":/iPhone|iPad/i.test(u)?"iPhone/iPad":/Windows/i.test(u)?"Windows":/Mac OS/i.test(u)?"Mac":"браузер"; }
const online = () => !!(API_URL && pass());
const pend = {suppliers:new Map(), customers:new Map(), products:new Map(), prices:new Map(), specs:new Map(), contracts:new Map(), journal:new Map(), costs:new Map(), doccosts:new Map(), psettings:new Map(), daytasks:new Map(), purchases:new Map(), pother:new Map(), cats:new Map(), invoices:new Map()};
const specOf = (c,p) => ((D.specs||{})[c]||{})[p] || {};
function dirtySpec(c,p){ const x=specOf(c,p); pend.specs.set(c+"|"+p,{s:++stamp, del:!(x.spec||x.ste||x.art)}); undoNote("specs",c+"|"+p); changed(); }
let serverOld=false;
let stamp=0;
function dirty(type,id,del){ if(type==="products" && !del){ const p=D.products.find(x=>x.id===id); if(p && (p.cat===undefined||p._ca) && p.name){ try{ const g=catGuess(p.name); if(g && g!==p.cat){ p.cat=g; p._ca=1; } }catch(e){} } }   /* новый товар — категория по названию, пока её не выбрали руками */
  pend[type].set(id,{s:++stamp, del:!!del}); undoNote(type,id); changed(); }
function dirtyPrice(c,p){ const v=custPrice(c,p); pend.prices.set(c+"|"+p,{s:++stamp, del:(v==null||v==="")}); undoNote("prices",c+"|"+p); changed(); }
let syncT=null, flushing=false;
const PENDK="frudom-docs-pend";
function savePend(){ try{ const o={}; Object.keys(pend).forEach(t=>{ if(pend[t].size) o[t]=[...pend[t].entries()]; }); lsSet(PENDK, Object.keys(o).length?JSON.stringify(o):null); }catch(e){} }
(function(){ try{ const o=JSON.parse(lsGet(PENDK)||"null"); if(!o) return; Object.keys(o).forEach(t=>{ if(!pend[t]) return; (o[t]||[]).forEach(([id,v])=>{ pend[t].set(id,v); if(v&&v.s>stamp) stamp=v.s; }); }); }catch(e){} })();
function changed(){ saveLocal(); savePend(); if(!online()) return; setStatus("wait","Есть несохранённое"); clearTimeout(syncT); syncT=setTimeout(flush,1200); }
const hasPending = () => Object.keys(pend).some(t=>pend[t].size && (t!=="pother" || D.poSrv) && (t!=="cats" || D.catSrv) && (t!=="invoices" || D.invSrv)) || evq.length>0;

/* запрос к таблице: не дольше 45 секунд; при ошибке понятно, что случилось — нет интернета, Google не ответил или таблица вернула ошибку */
async function apiFetch(url, opt){ const ac=window.AbortController?new AbortController():null, tm=ac&&setTimeout(()=>ac.abort(),(opt&&opt.tmo)||45000);
  let r; try{ r=await fetch(url, Object.assign({}, opt||{}, ac?{signal:ac.signal}:{})); }
  catch(e){ const x=new Error(e&&e.name==="AbortError"?"Google Таблица не ответила за "+Math.round(((opt&&opt.tmo)||45000)/1000)+" секунд":"нет интернета или Google недоступен"); x.net=true; throw x; } finally{ if(tm) clearTimeout(tm); }
  let j; try{ j=await r.json(); }catch(e){ const x=new Error("Google вернул ошибку "+(r.status||"")+" вместо данных — сервис временно перегружен"); x.net=true; throw x; }
  if(!j.ok){ const x=new Error(j.error||"ошибка хранилища"); x.resp=j; throw x; } return j; }
async function api(payload){
  const guarded=payload.action==="sync"||payload.action==="saveDoc";
  return apiFetch(API_URL, {method:"POST", body:JSON.stringify(Object.assign({key:pass(), user:curUser()}, payload, guarded?{protocol:1,base:requestBase(payload)}:{}))});
}
/* Server baselines survive reloads; pending edits are never used as an authoritative baseline. */
const SYNC_TABLES=['suppliers','customers','products','contracts','journal','costs','doccosts','psettings','daytasks','prices','specs','purchases','pother','cats','invoices'];
const BASE = D.syncBase = D.syncBase || {};
let conflictList = D.syncConflicts || [], syncBlocked = conflictList.length > 0, docSaving = false;
const syncKey=(t,r)=>t==='prices'||t==='specs'?r.customerId+'|'+r.productId:r.id;
const syncEq=(a,b)=>String(a==null?'':a)===String(b==null?'':b);
function localRow(t,id){
  if(t==='prices'||t==='specs'){const [c,p]=id.split('|'), v=(D[t]||{})[c]&&D[t][c][p]; return v==null?null:Object.assign({customerId:c,productId:p},t==='prices'?{price:String(v)}:v);}
  const r=(D[t]||[]).find(x=>x.id===id); return r?(t==='journal'?jRow(r):clone(r)):null;
}
function putLocalRow(t,id,r){
  if(t==='prices'||t==='specs'){const [c,p]=id.split('|');D[t]=D[t]||{};D[t][c]=D[t][c]||{};if(!r)delete D[t][c][p];else D[t][c][p]=t==='prices'?r.price:{spec:r.spec,ste:r.ste,art:r.art};return;}
  const list=D[t]=D[t]||[], i=list.findIndex(x=>x.id===id);
  let row=r&&clone(r);if(row&&t==='journal'){row.snap=JSON.parse(row.snap);row.sum=+row.sum||0;}
  if(i>=0){if(row)Object.assign(list[i],row);else list.splice(i,1);}else if(row)list.push(row);
}
function rememberBase(data){SYNC_TABLES.forEach(t=>{if(!Array.isArray(data[t]))return;BASE[t]={};data[t].forEach(r=>BASE[t][syncKey(t,r)]=clone(r));});saveLocal();}
function requestBase(payload){
  const out={}; const add=(t,id)=>{(out[t]=out[t]||{})[id]=clone((BASE[t]||{})[id]||null);};
  Object.entries(payload.changes||{}).forEach(([t,ch])=>{if(!SYNC_TABLES.includes(t)||!ch)return;(ch.upsert||[]).forEach(r=>add(t,syncKey(t,r)));(ch.del||[]).forEach(r=>add(t,typeof r==='string'?r:syncKey(t,r)));});
  if(payload.entry){add('journal',payload.entry.id);if(Object.prototype.hasOwnProperty.call(payload,'entryBase')){out.journal[payload.entry.id]=clone(payload.entryBase);return out;}const dr=D.draft;if(dr&&dr.id===payload.entry.id&&Object.prototype.hasOwnProperty.call(dr,'_editBase'))out.journal[payload.entry.id]=clone(dr._editBase);}
  return out;
}
function acceptRows(accepted,submitted){
  Object.entries(accepted||{}).forEach(([t,rows])=>Object.entries(rows).forEach(([id,row])=>{
    const sent=((submitted[t]||{}).upsert||[]).find(r=>syncKey(t,r)===id), now=localRow(t,id);
    (BASE[t]=BASE[t]||{})[id]=clone(row);
    if(sent&&now&&row){const merged=clone(row);Object.keys(now).forEach(k=>{if(!syncEq(now[k],sent[k]))merged[k]=now[k];});putLocalRow(t,id,merged);}
    else if(!pend[t].has(id))putLocalRow(t,id,row);
    if(t==='journal'&&D.draft&&D.draft.id===id)D.draft._editBase=clone(row);
  }));saveLocal();
}
function conflictSummary(r,t){if(!r)return 'Запись удалена';if(t==='journal'){try{const s=JSON.parse(r.snap);return '№ '+r.number+' от '+r.date+' · '+r.sum+' ₽\n'+(s.dr.lines||[]).map(l=>(l.name||(s.prods[l.productId]||{}).name||l.productId)+': '+l.qty+' × '+l.price).join('\n')+'\nАдрес: '+(s.dr.ship||'');}catch(e){return r.snap||'';}}return JSON.stringify(r,null,2);}
function showConflicts(list){
  syncBlocked=true;conflictList=list;D.syncConflicts=clone(list);saveLocal();clearTimeout(syncT);setStatus('err','Конфликт правок — нажмите здесь');
  let box=document.getElementById('fd-conflict');if(box)box.remove();box=document.createElement('dialog');box.id='fd-conflict';box.style.cssText='box-sizing:border-box;max-width:calc(100vw - 24px);width:min(760px,94vw);max-height:88vh;overflow:auto;border:0;border-radius:16px;padding:22px;font:15px Arial;color:#29232a';
  const x=list[0];if(!x)return;
  const fields=x.fields.filter(k=>!k.startsWith('_')&&k!=='snap');
  box.innerHTML='<h2 style="margin-top:0">Запись изменена другим пользователем</h2><p>Ваши правки сохранены на этом устройстве. Проверьте различия перед отправкой. Конфликтов: '+list.length+'</p><p><b>'+esc(x.table==='journal'?'Накладная № '+((x.proposed||x.current||{}).number||''):((x.proposed||x.current||{}).name||x.id))+'</b></p>'+fields.map(k=>'<p><b>'+esc(({name:'Название',address:'Юридический адрес',ship:'Адрес доставки',rs:'Расчётный счёт',bank:'Банк',price:'Цена',text:'Текст задачи',date:'Дата',done:'Выполнение'})[k]||k)+'</b><br>В таблице: '+esc((x.current||{})[k]||'—')+'<br>Ваш вариант: '+esc((localRow(x.table,x.id)||x.proposed||{})[k]||'—')+'</p>').join('')+(fields.length?'':'<div style="display:flex;flex-wrap:wrap;gap:12px"><div style="flex:1;min-width:220px"><b>В таблице</b><pre style="white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto">'+esc(conflictSummary(x.current,x.table))+'</pre></div><div style="flex:1;min-width:220px"><b>Ваш вариант</b><pre style="white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto">'+esc(conflictSummary(localRow(x.table,x.id),x.table))+'</pre></div></div>')+'<div style="display:flex;flex-wrap:wrap;gap:10px"><button data-choice="server">Оставить текущий вариант</button><button data-choice="mine">Сохранить мой вариант</button><button data-choice="later">Решить позже</button></div>';
  box.querySelectorAll('button').forEach(b=>{b.style.cssText='padding:12px;border:1px solid #ccc;border-radius:8px;background:#f6f2f4;cursor:pointer';b.onclick=()=>{
    if(b.dataset.choice==='later'){box.close();box.remove();return;}
    const t=x.table,id=x.id, mine=localRow(t,id), current=x.current, old=x.base, useMine=b.dataset.choice==='mine';
    let resolved=current&&clone(current);
    if(useMine){resolved=mine&&clone(mine);if(t!=='journal'&&mine&&current&&old){resolved=clone(current);Object.keys(mine).forEach(k=>{if(!syncEq(mine[k],old[k]))resolved[k]=mine[k];});}}
    else if(t!=='journal'&&mine&&current&&old&&!x.fields.some(k=>k.startsWith('_'))){Object.keys(mine).forEach(k=>{if(!x.fields.includes(k)&&!syncEq(mine[k],old[k]))resolved[k]=mine[k];});}
    (BASE[t]=BASE[t]||{})[id]=clone(current);putLocalRow(t,id,resolved);pend[t].delete(id);
    if(t==='journal'&&D.draft.id===id){if(resolved)D.draft=Object.assign(clone(JSON.parse(resolved.snap).dr),{_editBase:clone(current)});else D.draft=newDraft(D);}
    if(JSON.stringify(resolved)!==JSON.stringify(current))dirty(t,id,!resolved);
    if(t==='journal')docTasks([...new Set([current&&current.date,mine&&mine.date].filter(Boolean))],true);
    saveLocal();savePend();box.close();box.remove();conflictList.shift();D.syncConflicts=clone(conflictList);saveLocal();rerender();
    if(conflictList.length)showConflicts(conflictList);else{syncBlocked=false;flush();}
  };});
  box.addEventListener('cancel',()=>{box.remove();});document.body.appendChild(box);box.showModal();
}

function buildChanges(){
  const ch={}, sent={};
  ["suppliers","customers","cats","products","contracts","journal","costs","doccosts","psettings","daytasks","purchases","pother","invoices"].forEach(t=>{
    if(!pend[t].size || (t==="pother" && !D.poSrv) || (t==="cats" && !D.catSrv) || (t==="invoices" && !D.invSrv)) return;   /* старый скрипт таблицы не знает этот лист — держим на устройстве */ const up=[], del=[]; sent[t]=new Map(pend[t]);
    pend[t].forEach((v,id)=>{ if(v.del) del.push(id); else { const o = t==="journal" ? jRow(D.journal.find(x=>x.id===id)) : (D[t]||[]).find(x=>x.id===id); if(o) up.push(o); else del.push(id); } });
    ch[t]={upsert:up, del};
  });
  if(pend.specs.size){ const up=[], del=[]; sent.specs=new Map(pend.specs);
    pend.specs.forEach((v,k)=>{ const [c,p]=k.split("|"), x=specOf(c,p); if(v.del||!(x.spec||x.ste||x.art)) del.push({customerId:c, productId:p}); else up.push({customerId:c, productId:p, spec:x.spec||"", ste:x.ste||"", art:x.art||""}); });
    ch.specs={upsert:up, del}; }
  if(pend.prices.size){ const up=[], del=[]; sent.prices=new Map(pend.prices);
    pend.prices.forEach((v,k)=>{ const [c,p]=k.split("|"); const pr=custPrice(c,p); if(v.del||pr==null||pr==="") del.push({customerId:c, productId:p}); else up.push({customerId:c, productId:p, price:String(pr)}); });
    ch.prices={upsert:up, del}; }
  const evn=Math.min(evq.length,100); if(evn) ch.events=evq.slice(0,evn);
  return Object.keys(ch).length ? {ch:clone(ch), sent, evn} : null;
}
function jRow(e){ if(!e) return null; return {id:e.id, supplierId:e.supplierId, customerId:e.customerId, number:String(e.number), date:e.date, sum:String(e.sum), updated:e.updated||"", snap:JSON.stringify(e.snap)}; }
function sentOk(b){ Object.keys(b.sent).forEach(t=>b.sent[t].forEach((v,id)=>{ const cur=pend[t].get(id); if(cur&&cur.s===v.s) pend[t].delete(id); })); savePend();
  if(b.evn){ evq.splice(0,b.evn); lsSet(EKEY, JSON.stringify(evq)); } }
async function flush(){
  if(!online() || syncBlocked) return;
  if(docSaving){clearTimeout(syncT);syncT=setTimeout(flush,700);return;}
  if(flushing){ clearTimeout(syncT); syncT=setTimeout(flush,700); return; }
  const b=buildChanges(); if(!b){ setStatus("ok"); return; }
  flushing=true; setStatus("saving","Сохраняю…");
  try{
    const result=await api({action:"sync", changes:b.ch}); sentOk(b); acceptRows(result.accepted,b.ch); if(b.ch.products && curTab==="products") try{ pdAfterSync(); }catch(e){}
    setStatus(hasPending()?"wait":"ok", hasPending()?"Есть несохранённое":"");
    if(hasPending()){ clearTimeout(syncT); syncT=setTimeout(flush,500); }
  }catch(e){ if(e.resp&&e.resp.conflicts){showConflicts(e.resp.conflicts);return;} handleErr(e); clearTimeout(syncT); syncT=setTimeout(flush,15000); }
  finally{ flushing=false; }
}
/* ---------- всплывающие уведомления ---------- */
const TICON={ok:'<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>',
  warn:'<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"><path d="M12 6v8M12 18.5v.5"/></svg>',
  err:'<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"><path d="M7 7l10 10M17 7L7 17"/></svg>',
  info:'<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"><path d="M12 11v7M12 6v.5"/></svg>'};
/* уведомления — всегда на самом верхнем слое, поверх открытых окон (карточка товара, документа, просмотр файла).
   Окна открываются через showModal и встают в «верхний слой» браузера; уведомления тоже кладём туда (popover) и поднимаем над последним окном. */
function toastTop(){ const box=document.getElementById("fd-toasts"); if(!box || !box.children.length) return;
  /* внутрь верхнего открытого окна — иначе браузер делает уведомление некликабельным (всё вне окна «заморожено») */
  const dl=[...document.querySelectorAll("dialog[open]")].filter(d=>!d.classList.contains("out")).pop(), host=dl||document.body;
  const pop=typeof box.showPopover==="function";
  if(pop && !box.hasAttribute("popover")) box.setAttribute("popover","manual");
  if(box.parentElement!==host) host.appendChild(box);
  if(pop){ try{ if(box.matches(":popover-open")) box.hidePopover(); box.showPopover(); }catch(e){} } }
(function(){ const P=window.HTMLDialogElement&&HTMLDialogElement.prototype; if(!P||P.__fdTop) return; P.__fdTop=1; const sm=P.showModal;
  P.showModal=function(){ const r=sm.apply(this,arguments); try{ toastTop(); }catch(e){} return r; };
  /* окно закрывается — уведомления переезжают обратно и остаются видны */
  const back=d=>{ const box=document.getElementById("fd-toasts"); if(box && d && d.contains && d.contains(box)){ document.body.appendChild(box); toastTop(); } };
  document.addEventListener("close",e=>back(e.target), true);
  new MutationObserver(ms=>ms.forEach(m=>m.removedNodes.forEach(n=>{ const b=n.nodeType===1 ? (n.id==="fd-toasts" ? n : n.querySelector && n.querySelector("#fd-toasts")) : null; if(b && !b.isConnected){ document.body.appendChild(b); toastTop(); } }))).observe(document.body,{childList:true, subtree:true}); })();
function toast(type, title, text, opt){
  opt=opt||{}; let box=document.getElementById("fd-toasts");
  if(!box){ box=document.createElement("div"); box.id="fd-toasts"; document.body.appendChild(box); }
  [...box.children].forEach(x=>{ if(x.dataset.key===title+"|"+(text||"")) x.remove(); });
  const ms=opt.ms || (type==="err"?12000:type==="warn"?8000:opt.action?7000:4500);
  const el=document.createElement("div"); el.className="fd-toast t-"+type; el.dataset.key=title+"|"+(text||"");
  el.setAttribute("role", type==="err"?"alert":"status"); el.setAttribute("aria-live", type==="err"?"assertive":"polite");
  el.innerHTML=`<div class="ic">${TICON[type]||TICON.info}</div><div class="tx"><b>${esc(title)}</b>${text?`<span>${esc(text)}</span>`:""}${opt.action?`<button type="button" class="ta">${esc(opt.action.label)}</button>`:""}</div><button type="button" class="tc" aria-label="Закрыть">×</button><i class="pb" style="animation-duration:${ms}ms"></i>`;
  box.appendChild(el); toastTop(); const maxN=window.innerWidth<=600?2:3; while(box.children.length>maxN) box.firstElementChild.remove();
  requestAnimationFrame(()=>requestAnimationFrame(()=>el.classList.add("in")));
  let left=ms, t0=Date.now(), timer=setTimeout(close, ms), gone=false;
  function close(){ if(gone) return; gone=true; clearTimeout(timer); el.classList.remove("in"); el.classList.add("out"); setTimeout(()=>el.remove(), 260); }
  const pause=()=>{ clearTimeout(timer); left-=Date.now()-t0; el.classList.add("paused"); }, resume=()=>{ t0=Date.now(); clearTimeout(timer); timer=setTimeout(close, Math.max(1500,left)); el.classList.remove("paused"); };
  el.addEventListener("mouseenter", pause); el.addEventListener("mouseleave", resume);
  el.querySelector(".tc").onclick=close;
  if(opt.action) el.querySelector(".ta").onclick=()=>{ try{ opt.action.fn(); } finally{ close(); } };
  /* на телефоне: смахнуть в сторону — закрыть */
  let sx=null; el.addEventListener("touchstart",e=>{ sx=e.touches[0].clientX; pause(); },{passive:true});
  el.addEventListener("touchmove",e=>{ if(sx==null) return; const dx=e.touches[0].clientX-sx; el.style.transform=`translateX(${dx}px)`; el.style.opacity=String(Math.max(0,1-Math.abs(dx)/220)); },{passive:true});
  el.addEventListener("touchend",e=>{ if(sx==null) return; const dx=(e.changedTouches[0]||{}).clientX-sx; sx=null; if(Math.abs(dx)>80){ el.style.transition="transform .2s, opacity .2s"; el.style.transform=`translateX(${dx>0?400:-400}px)`; el.style.opacity="0"; gone=true; clearTimeout(timer); setTimeout(()=>el.remove(),200); } else { el.style.transform=""; el.style.opacity=""; resume(); } });
  return close;
}
let netToastAt=0;
function handleErr(e){ if(e.message==="auth"){ showLogin("Неверный пароль"); setStatus("err","Нужен вход"); toast("err","Неверный пароль","Таблица не приняла пароль. Введите его ещё раз в окне входа."); }
  else if(e && !e.net){ setStatus("err","Ошибка таблицы, повторю"); if(Date.now()-netToastAt>60000){ netToastAt=Date.now(); toast("warn","Таблица ответила ошибкой","«"+String(e.message||e).slice(0,160)+"». Всё сохранено на этом устройстве, повторю сам. Если повторяется — пришлите этот текст Claude."); } }
  else { setStatus("err","Не сохранено — нет связи, повторю"); if(Date.now()-netToastAt>60000){ netToastAt=Date.now(); toast("warn","Нет связи с Google Таблицей",(e&&e.message?"Причина: "+e.message+". ":"")+"Всё сохранено на этом устройстве и отправится автоматически, когда связь появится. Ничего делать не нужно."); } } }

const NEED_VER=20;   /* какая версия Code.gs нужна этому сайту (CODE_VER в Code.gs) */
function srvVerCheck(v){ const el=$("#srvOld"); if(!el) return; const old=(+v||0)<NEED_VER; el.hidden=!old || docLimited(); D.srvVer=+v||0; }
document.addEventListener("click",e=>{ if(!e.target.closest || !e.target.closest("#srvOldHow")) return; openCard(`<div class="dc-head"><div><div class="dc-kicker">Code.gs</div><h3>Как обновить скрипт таблицы</h3></div><button class="dc-x" data-dc="close" aria-label="Закрыть">×</button></div>
  <ol class="srvsteps"><li>GitHub → файл <b>dev/Code.template.gs</b> → кнопка «Copy raw file» (два квадратика).</li><li>Таблица «Документы ФД» → «Расширения» → «Apps Script» → файл <b>Код.gs</b> → Ctrl+A → Ctrl+V → «Сохранить». Файл «Пароли.gs» не трогать.</li><li>«Начать развёртывание» → «Управление развёртываниями» → карандаш → «Версия: новая версия» → «Развернуть».</li><li>Обновите эту страницу — жёлтая плашка исчезнет.</li></ol>
  <div class="dc-acts"><button class="btn pri" data-dc="close">Понятно</button></div>`, false, ()=>{}); });
function applyServer(d){
  rememberBase(d);
  D.suppliers = d.suppliers.map(x=>Object.assign(x,{next:+x.next||1, vat:x.vat||"none"}));
  D.customers = d.customers.map(x=>Object.assign(x,{acct:x.acct||"bank"}));
  const catMig = Array.isArray(d.cats) && !d.cats.length && (D.cats||[]).length && !D.catSrv;   /* скрипт только что обновили, а на устройстве уже есть категории */
  { const old={}; (D.products||[]).forEach(p=>{ if(p.cat) old[p.id]=p.cat; });
    D.products = d.products;
    /* старый скрипт не знает категорий — не теряем то, что расставлено на устройстве */
    if(catMig || !Array.isArray(d.cats) || (d.products.length && !("cat" in d.products[0]))) D.products.forEach(p=>{ if(old[p.id] && !p.cat) p.cat=old[p.id]; }); }
  if(Array.isArray(d.cats)){
    if(catMig){ D.catSrv=true; D.cats.forEach(c=>dirty("cats",c.id)); D.products.forEach(p=>{ if(p.cat) dirty("products",p.id); }); }   /* скрипт только что обновили: категории с устройства уходят в таблицу */
    else { D.cats=d.cats; D.catSrv=true; } }
  else { D.cats=D.cats||[]; D.catSrv=false; }
  if(Array.isArray(d.invoices)){ D.invoices=d.invoices; D.invSrv=true; } else if(!isStaff()){ D.invoices=D.invoices||[]; D.invSrv=false; }   /* счета на оплату: лист есть только в Code.gs ≥ 14 */
  serverOld = !Array.isArray(d.contracts) || !Array.isArray(d.specs) || (d.customers.length>0 && !("branches" in d.customers[0]));
  if(Array.isArray(d.contracts)) D.contracts = d.contracts;
  if(Array.isArray(d.specs)){ D.specs={}; d.specs.forEach(r=>{ (D.specs[r.customerId]=D.specs[r.customerId]||{})[r.productId]={spec:r.spec, ste:r.ste, art:r.art}; }); }
  D.prices = {}; d.prices.forEach(r=>{ (D.prices[r.customerId]=D.prices[r.customerId]||{})[r.productId]=r.price; });
  const wasDemo=!!D.demo, srv=new Set(d.journal.map(r=>r.id)), lost=wasDemo?[]:(D.journal||[]).filter(j=>j&&j.snap&&j.id&&!srv.has(j.id)&&(Date.now()-Date.parse(j.updated||0))<45*864e5);
  D.journal = d.journal.map(r=>{ let snap=null; try{ snap=JSON.parse(r.snap); }catch(e){} return {id:r.id, supplierId:r.supplierId, customerId:r.customerId, number:r.number, date:r.date, sum:+r.sum||0, updated:r.updated, snap}; })
    .filter(e=>e.snap).sort((a,b)=> (b.date+b.updated).localeCompare(a.date+a.updated));
  if(lost.length){
    lost.forEach(j=>{D.journal.push(j);dirty("journal",j.id);});
    showConflicts(lost.map(j=>({table:"journal",id:j.id,fields:["_missing"],current:null,base:jRow(j),proposed:jRow(j)})));
  }
  if(Array.isArray(d.daytasks)) D.daytasks = d.daytasks;
  D.demo=false; $("#demoNote").hidden=true;
  if(D.draft.supplierId && !D.suppliers.some(x=>x.id===D.draft.supplierId) && D.suppliers[0]) D.draft.supplierId=D.suppliers[0].id;
  if(D.draft.customerId && !D.customers.some(x=>x.id===D.draft.customerId)) D.draft.customerId=(D.customers[0]||{}).id||"";
  if(!isStaff()) patchAll(); try{ catSeed(); }catch(e){} saveLocal();
  if(!isStaff() && Array.isArray(d.daytasks) && !lsGet("frudom-auto-bf2")){ const t=todayISO(); docTasks(D.journal.filter(j=>j.snap && !isArch(j) && j.date>=t).map(j=>j.date), true); lsSet("frudom-auto-bf2","1"); }
}
let lastPullAt=0;
/* фоновое обновление не должно «мигать»: те же данные — экран не перерисовываем, новые — перерисовываем без анимации появления */
let pullSig="", pullN=0;
const fdSig = o => { try{ const s=JSON.stringify(o); let h=0; for(let i=0;i<s.length;i+=7) h=(h*31+s.charCodeAt(i))|0; return s.length+":"+h; }catch(e){ return String(Math.random()); } };
function fdCalm(){ const m=document.getElementById("fd-main"); if(!m || !m.getAnimations) return;
  try{ m.getAnimations({subtree:true}).forEach(a=>{ if(typeof CSSAnimation!=="undefined" && !(a instanceof CSSAnimation)) return; try{ a.finish(); }catch(e){} }); }catch(e){} }
async function pull(force){
  if(syncBlocked){showConflicts(conflictList);return;}
  if(!online()) return;
  if(hasPending()){ await flush(); if(hasPending()) return; }
  setStatus("saving","Загружаю…");
  try{
    const j = await apiFetch(API_URL+"?action=load&key="+encodeURIComponent(pass())+"&user="+encodeURIComponent(curUser())); lastPullAt=Date.now(); eisServerReady=j.eis===1; aktSrv=j.akt===1;
    if(hasPending()) { setStatus("wait","Есть несохранённое"); return; }
    if(j.me){ lsSet(MKEY, JSON.stringify(j.me)); applyRole(); }
    if("prefs" in j) serverPrefs(j.prefs); if(prefsDirty) pushPrefs();
    srvVerCheck(j.ver);   /* версию скрипта знаем сразу, даже если таблица пустая */
    if(j.data && Array.isArray(j.data.invoices)){ D.invSrv=true; D.invoices=D.invoices||[]; }   /* лист счетов есть — даже при пустой таблице */
    if(!j.data.suppliers.length){ // пустая таблица: выгрузить то, что есть здесь
      patchAll();
      D.suppliers.forEach(x=>dirty("suppliers",x.id)); D.customers.forEach(x=>dirty("customers",x.id)); D.products.forEach(x=>dirty("products",x.id)); D.contracts.forEach(x=>dirty("contracts",x.id));
      Object.keys(D.prices).forEach(c=>Object.keys(D.prices[c]).forEach(p=>dirtyPrice(c,p))); D.journal.forEach(e=>e.snap&&dirty("journal",e.id));
      Object.keys(D.specs).forEach(c=>Object.keys(D.specs[c]).forEach(p=>dirtySpec(c,p)));
      await flush(); setStatus("ok","Таблица заполнена"); return;
    }
    const sig=fdSig(j.data);   /* до applyServer — он дописывает поля в эти же объекты */
    applyServer(j.data); srvVerCheck(j.ver); bkTick(); if(syncBlocked){rerender();return;} setStatus("ok"); skLoad(true); if(j.concurrency!==1)toast("warn","Нужно обновить Code.gs","Защита от одновременных правок заработает после установки нового скрипта таблицы."); if(serverOld) setStatus("err","Обновите скрипт таблицы (новая версия)");
    const same=pullN>0 && sig===pullSig; pullSig=sig; pullN++;
    if(!same){ rerender(); if(pullN>1) fdCalm(); } setTimeout(plAuto, 1500);
  }catch(e){ handleErr(e); }
}
function setStatus(s, text){
  const el=$("#fd-status"); el.dataset.s=s;
  el.querySelector("span").textContent = text || ({ok:"Сохранено в таблице", local:"Только на этом устройстве", saving:"Сохраняю…", wait:"Есть несохранённое", err:"Ошибка"}[s]);
}
