  lsSet(PKEY,null); lsSet(MKEY,null); lsSet(UKEY,null); evCache=null; delete D.costs; delete D.doccosts; delete D.psettings; delete D.zk; delete D.purchases; delete D.zkSrv; delete D.pother; delete D.poSrv; pfLoaded=false; saveLocal();
  const nav=$("#fd-app nav.tabs"); nav.classList.remove("editing"); $("#tab-bar").hidden=true; prefsDirty=false;
  showLogin(); setStatus("local"); applyRole(); toast("info","Вы вышли из системы","");
