$("#d-save").onclick=async()=>{
  const b=$("#d-save"), msg=$("#d-saved"); if(!calc(D.draft).lines.length){ msg.textContent="Добавьте хотя бы один товар с количеством."; toast("err","Нет товаров в документе","Выберите товар и укажите количество больше нуля — затем нажмите кнопку снова."); return; }
  const edit=D.journal.some(j=>j.id===D.draft.id); b.disabled=true;
  try{ const note=await commitDoc(); if(typeof bnMulNext==="function" && bnMulNext(note)) return; const dr=D.draft, n=dr.number;
    const keep={supplierId:dr.supplierId, customerId:dr.customerId, branchId:dr.branchId, contractId:dr.contractId, basis:dr.basis, date:dr.date, ship:dr.ship};
    D.draft=Object.assign(newDraft(D), keep); D.draft.number=nextNum(keep.supplierId, keep.customerId); saveLocal(); renderDoc();
    $("#d-saved").textContent=(note||"")+"Документ № "+n+(edit?" обновлён":" сохранён")+" в журнале — распечатать можно оттуда в любой момент. Форма очищена для следующего документа (№ "+D.draft.number+")."; docToast("Распечатать — во вкладке «Журнал». Форма готова для № "+D.draft.number+"."); }
  catch(e){ msg.textContent="Не получилось сохранить: "+e.message; toast("err","Не получилось сохранить документ", e.message+". Проверьте интернет и нажмите кнопку ещё раз."); }
  finally{ b.disabled=false; }
};
$("#d-new").onclick=$("#d-new2").onclick=e=>{ const bt=e.currentTarget; if(!armed(bt,"Точно очистить форму?")) return; delete bt.dataset.armed; bt.classList.remove("armed"); bt.textContent=bt.id==="d-new2"?"Очистить":"Очистить и начать новый"; const s=D.draft.supplierId, c=D.draft.customerId; D.draft=newDraft(D); D.draft.supplierId=s; D.draft.customerId=c;
  D.draft.contractId=pickCtr(); { const x=ctr(D.draft.contractId); if(x&&x.supplierId) D.draft.supplierId=x.supplierId; } D.draft.number=nextNum(D.draft.supplierId, c); D.draft.basis=(ctr(D.draft.contractId)||{}).basis||""; saveLocal(); renderDoc(); $("#d-saved").textContent=""; };

