  $("#o-cus").innerHTML=opts(D.customers, o.customerId); $("#o-sup").innerHTML=opts(D.suppliers, o.supplierId);
  const bl=branches(cus(o.customerId)); $("#o-brwrap").hidden=!bl.length;
