function oView(o){ const v=((getPrefs().ov||{})[o.customerId]); return v==="v"||v==="h" ? v : (oBrMode(o)?"v":"h"); }
function oSetView(v){ const o=O(), p=getPrefs(); p.ov=p.ov||{}; p.ov[o.customerId]=v; setPrefs(p,true); renderOrderGrid(); const t=$("#o-tbl"); if(t){ t.classList.remove("oflip"); void t.offsetWidth; t.classList.add("oflip"); } }
