const daysSince = iso => { if(!iso) return 0; const a=new Date(iso+"T12:00:00"), b=new Date(todayISO()+"T12:00:00"); return Math.max(0, Math.round((b-a)/864e5)); };
const ageCls = d => d>30 ? "old" : d>10 ? "mid" : "";
