  dc.lines=JSON.stringify(L); dc.paid = sum<=0 ? "" : sum>=tot-0.005 ? "да, "+fd(L._pay.d) : "частично: "+fm(sum)+" из "+fm(tot)+" ₽, "+fd(L._pay.d);
