  $("#pf-cards").innerHTML=`<div class="pfk">${tile("rev","Выручка",T.rev,docs.length+" "+plural(docs.length,["накладная","накладные","накладных"]))}${tile("cost","Закупка",T.cost)}${tile("tax","Налог "+taxL,T.tax)}${tile("gross","Валовая прибыль",T.gross,"после налога · маржа "+pct(T.gross,T.rev),"soft")}${tile("exp","Прочие расходы",r2(T.exp+T.oexp),T.exp&&T.oexp?"по накладным "+fm(T.exp)+" · общие "+fm(T.oexp):"")}${tile("inc","Прочие доходы",T.oinc)}${tile("net","Чистая прибыль, ₽",T.net,"маржа "+pct(T.net,T.rev),"main")}${(()=>{ const P=r2(pfArr("pother").filter(x=>x.kind===PO_PER && x.date>=d1 && x.date<=d2).reduce((a,x)=>a+(+x.sum||0),0)); return P>0 && !f.cus && !f.sup ? tile("own","Остаётся после личных",r2(T.net-P),"личные траты "+fm(P)) : ""; })()}${tile("paid","Оплачено за эти накладные",T.paid,"","ok")}${tile("due","Ждём оплату",T.due,docs.filter(x=>x.pay.st!=="paid").length+" "+plural(docs.filter(x=>x.pay.st!=="paid").length,["накладная","накладные","накладных"]),T.due>0?"warn":"")}</div>${bar}`;
