function bundleCard(g, arch){
  if(!g.length) return; const ks=g.map(j=>calc(j.snap.dr, j.snap)), w={main:gTitle(g)}, lim=docLimited(), sum=r2(ks.reduce((a,k)=>a+k.t.sum,0)), kg=ks.reduce((a,k)=>a+k.t.kg,0);
  const nums=g.map(j=>j.number), hist=[].concat(...g.map(j=>histOf(j).map(x=>Object.assign(x,{num:j.number}))));
  const info=[["Поставщик",g[0].snap.s.name||""],["Основание",g[0].snap.dr.basis||""],["Документы","№ "+(nums.length>2?nums[0]+"–"+nums[nums.length-1]:nums.join(", "))]].filter(x=>x[1]);
  const docs=g.map((j,i)=>{ const k=ks[i]; return `<section class="dc-doc" style="animation-delay:${Math.min(i,8)*0.04}s"><button class="dc-dh" data-dc="doc" data-id="${j.id}" title="Открыть документ"><span><b>№ ${esc(j.number)}</b> · ${esc(kLbl(j)||stLabel(k.dr.ship||k.c.address||"", k.c.address))}</span><span class="s">${fm(k.t.sum)} ₽ ›</span></button>${linesTable(k)}</section>`; }).join("");
  const acts = arch ? `<button class="btn" data-dc="close">Закрыть</button>`
    : `<button class="btn" data-dc="decl">Декларации</button><button class="btn" data-dc="gpdf" data-k="invoice,torg12">Счета+ТОРГ</button><button class="btn" data-dc="gpdf" data-k="upd">Все УПД</button>`+(me().admin?`<button class="btn" data-bzk="toggle" aria-expanded="false">${bzHas(g)}</button>`:"")+(lim?"":`<button class="btn pri" data-dc="gedit">Редактировать комплект</button>`);
  { const ids=g.map(x=>x.id); CARD_RE=()=>{ const gg=ids.map(id=>D.journal.find(y=>y.id===id)).filter(Boolean); if(gg.length) bundleCard(gg, arch); else toast("info","Комплекта уже нет"); }; }
  openCard(`<div class="dc-head"><div><div class="dc-kicker">Комплект · ${g.length} ${docsWord(g.length)} · ${fd(g[0].date)}</div><h3>${esc(w.main)}</h3></div><button class="dc-x" data-dc="close" aria-label="Закрыть">×</button></div>
    <dl class="dc-info">${info.map(([a,b])=>`<div><dt>${a}</dt><dd>${esc(b)}</dd></div>`).join("")}</dl>
    <div class="dc-docs">${docs}</div>
    <div class="dc-total"><span>${g.length} ${docsWord(g.length)}${kg?" · "+nq3(kg)+" кг":""}</span><b>${fm(sum)} ₽</b></div>
    ${histHtml(hist)}
    ${!arch&&me().admin?`<div class="dc-zk" id="bz-zk" data-ids="${esc(g.map(j=>j.id).join(","))}"><div class="dc-zki" id="bz-zki"></div></div>`:""}
    <div class="dc-acts">${acts}</div>`, true, (a,b)=>{
      if(a==="doc"){ const j=D.journal.find(x=>x.id===b.dataset.id); if(j) docCard(j, arch); return; }
      if(a==="gedit"){ bundleEdit(g); return; }
      if(a==="decl"){ skDeclDocs(g); return; }
      if(a==="gpdf"){ const kinds=b.dataset.k.split(","); showPreviewSet(ks.flatMap(k=>kinds.map(kind=>({kind,k}))), kinds.map(x=>KSHORT[x]).join(" и ")+" № "+(nums.length>1?nums[0]+"–"+nums[nums.length-1]:nums[0])+" от "+fd(g[0].date)+" — "+shortCus(ks[0])); } });
}
/* ---------- редактирование комплекта во вкладке «Заявка» ---------- */
function bundleEdit(g){
  if(docLimited()) return; const live=g.filter(j=>j.snap&&!isArch(j)).sort(jNumSort); if(!live.length) return;
  const brm=oBrMode({customerId:live[0].customerId}), rk=j=>brm?OP_PFX+(j.snap.dr.branchId||""):(j.snap.dr.ship||j.snap.c.address||"");
  const seen={}; for(const j of live){ const a=rk(j); if(seen[a]){ toast("warn","Комплект нельзя открыть в «Заявке»","№ "+seen[a]+" и № "+j.number+" — "+(brm?"на одно подразделение":"на один адрес")+". Отредактируйте эти документы по отдельности кнопкой «Изменить»."); return; } seen[a]=j.number; }
  const j0=live[0], cs=new Set(live.map(j=>j.customerId+"|"+j.supplierId+"|"+(brm?"":(j.snap.dr.branchId||""))));
  if(cs.size>1){ toast("warn","Комплект нельзя открыть в «Заявке»","В комплекте документы разных заказчиков или поставщиков. Отредактируйте их по отдельности."); return; }
  const o=O(), backup=o.edit ? o.edit.backup : clone({customerId:o.customerId, supplierId:o.supplierId, branchId:o.branchId, date:o.date, qty:o.qty, num:o.num, extra:o.extra});
  const ids={}, price={};
  o.customerId=j0.customerId; o.supplierId=j0.supplierId; o.branchId=j0.snap.dr.branchId||""; o.date=j0.date; o.qty={}; o.num={}; o.extra=[];
  live.forEach(j=>{ const a=rk(j); ids[a]=j.id; o.num[a]=String(j.number); const q={};
    j.snap.dr.lines.forEach(l=>{ if(!l.productId||!(+l.qty>0)) return; q[l.productId]=String(r3((+q[l.productId]||0)+(+l.qty))); if(price[l.productId]==null) price[l.productId]=+l.price||0; }); o.qty[a]=q; });
  o.edit={ids, price, batch:(j0.snap.meta||{}).batch||"", nums:live.map(j=>j.number), backup};
  const {all}=oAddrs(o); if(!brm) Object.keys(ids).forEach(a=>{ if(!all.includes(a)) o.extra.push(a); });
  $("#o-done").innerHTML=""; $("#o-msg").textContent=""; saveLocal(); showTab("order"); renderOrder();
  toast("ok","Комплект открыт для правки","Измените количества, добавьте или уберите адреса и нажмите «Сохранить изменения комплекта».");
}
function bundleEditEnd(restore){ const o=O(); if(!o.edit) return; const b=o.edit.backup||{}; delete o.edit;
  if(restore!==false) Object.assign(o, {customerId:b.customerId, supplierId:b.supplierId, branchId:b.branchId, date:b.date, qty:b.qty||{}, num:b.num||{}, extra:b.extra||[]});
  saveLocal(); renderOrder(); }
