/* меню «Ещё» — поверх страницы, у кнопки; если внизу места нет — открывается вверх */
function placeMore(d){ const m=d.querySelector(".menu"), s=d.querySelector("summary"); if(!m||!s) return;
  m.style.position="fixed"; m.style.visibility="hidden"; m.style.left="0px"; m.style.top="0px"; m.style.right="auto";
  const r=s.getBoundingClientRect(), mw=m.offsetWidth, mh=m.offsetHeight, vw=document.documentElement.clientWidth, vh=window.innerHeight;
  let left=Math.min(Math.max(8, r.right-mw), vw-mw-8), top=r.bottom+6; if(top+mh>vh-8) top=Math.max(8, r.top-mh-6);
  m.style.left=left+"px"; m.style.top=top+"px"; m.style.visibility=""; d.classList.add("placed"); moreAt={x:window.scrollX, y:window.scrollY, t:Date.now()}; }
