    make:()=>({id:uid(), name:"ИП ", fio:"", inn:"", kpp:"", ogrn:"", ogrnDate:"", address:"", phone:"", bank:"", bik:"", rs:"", ks:"", vat:"none", next:1, accountant:""}),
