function renderSignBox(sid){ const s=sup(sid), box=$("#sup-sign"); if(!box) return; if(!s||!s.id||isStaff()){ box.innerHTML=""; return; }
  const cell=(k,title,hint)=>`<div class="sgcell"><div class="sgprev${k==="stamp"?" st":""}">${s[k]?`<img src="${s[k]}" alt="">`:`<span class="muted">${hint}</span>`}</div>
    <div class="row"><label class="btn sm">${s[k]?"Заменить":"Загрузить"} ${title}<input type="file" accept="image/*" data-sgup="${k}" hidden></label>${s[k]?`<button class="btn ghost sm danger" data-sgdel="${k}">Удалить</button>`:""}</div></div>`;
  box.innerHTML=`<h2>Печать и подпись <small>для документов «с печатью и подписью»</small></h2>
    <p class="muted">Сфотографируйте или отсканируйте печать и подпись на белом листе — белый фон сайт уберёт сам. Они ставятся только на стороне поставщика (у «Отпуск груза разрешил», «Товар передал», в счёте) и только когда включена галочка «С печатью и подписью».</p>
    <div class="sggrid">${cell("stamp","печать","Печати нет")}${cell("sign","подпись","Подписи нет")}</div>`; }
async function prepSign(file, kind){
  const img=await new Promise((ok,bad)=>{ const u=URL.createObjectURL(file), im=new Image(); im.onload=()=>{ ok(im); URL.revokeObjectURL(u); }; im.onerror=()=>bad(new Error("не удалось открыть картинку")); im.src=u; });
  const W=img.naturalWidth, H=img.naturalHeight, sc=Math.min(1, 1600/Math.max(W,H)), w=Math.round(W*sc), h=Math.round(H*sc);
  const c=document.createElement("canvas"); c.width=w; c.height=h; const x=c.getContext("2d"); x.drawImage(img,0,0,w,h);
  const d=x.getImageData(0,0,w,h), a=d.data; let x0=w,y0=h,x1=0,y1=0;
  for(let i=0;i<a.length;i+=4){ const r=a[i],g=a[i+1],b=a[i+2], mx=Math.max(r,g,b), mn=Math.min(r,g,b), lum=(r+g+b)/3, sat=mx-mn;
    /* светлое и малонасыщенное — фон бумаги → прозрачно; чернила остаются */
    let al;
    if(kind==="stamp"){ al = Math.max(0, Math.min(255, (b-g-12)*9)); if(al>0){ a[i]=Math.round(r*0.55); a[i+1]=Math.round(g*0.6); a[i+2]=Math.min(255,Math.round(b*0.95)); } }            /* печать синяя/фиолетовая: оставляем только её цвет, чёрный текст бланка убираем */
    else { al = sat>40 ? 255 : Math.max(0, Math.min(255, (215-lum)*4)); if(lum>235 && sat<25) al=0; }
    a[i+3]=Math.min(a[i+3],al);
    if(al>40){ const p=i/4, px=p%w, py=(p/w)|0; if(px<x0)x0=px; if(px>x1)x1=px; if(py<y0)y0=py; if(py>y1)y1=py; } }
  x.putImageData(d,0,0); if(x1<=x0||y1<=y0) throw new Error("на картинке не видно печати или подписи");
  const pad=6; x0=Math.max(0,x0-pad); y0=Math.max(0,y0-pad); x1=Math.min(w-1,x1+pad); y1=Math.min(h-1,y1+pad);
  let max = kind==="stamp" ? 420 : 520, out="";
  for(let tries=0; tries<6; tries++){ const cw=x1-x0+1, ch=y1-y0+1, s2=Math.min(1, max/Math.max(cw,ch)), o=document.createElement("canvas"); o.width=Math.round(cw*s2); o.height=Math.round(ch*s2);
    o.getContext("2d").drawImage(c,x0,y0,cw,ch,0,0,o.width,o.height);
    out=o.toDataURL("image/webp",0.82); if(!/^data:image\/webp/.test(out)) out=o.toDataURL("image/png");
    if(out.length<45000) break; max=Math.round(max*0.8); }
  if(out.length>=45000) throw new Error("картинка слишком большая — обрежьте её поплотнее");
  return out; }
$("#sup-sign").addEventListener("change",async e=>{ const k=e.target.dataset.sgup; if(!k) return; const f=e.target.files[0]; e.target.value=""; if(!f) return; const s=sup(editorSel.suppliers); if(!s||!s.id) return;
  try{ s[k]=await prepSign(f,k); dirty("suppliers",s.id); saveLocal(); renderSignBox(s.id); syncSignUI(); toast("ok", k==="stamp"?"Печать загружена":"Подпись загружена", "Белый фон убран. Проверьте, как она выглядит в документе: «С печатью и подписью» в окне документа."); logEv("Справочники",(k==="stamp"?"Загружена печать":"Загружена подпись")+" — "+s.name); }
  catch(err){ toast("err","Не получилось загрузить", err.message+"."); } });
$("#sup-sign").addEventListener("click",e=>{ const b=e.target.closest("[data-sgdel]"); if(!b) return; const s=sup(editorSel.suppliers); if(!s) return;
  if(!b.dataset.armed){ b.dataset.armed=1; b.textContent="Точно удалить?"; return; } const k=b.dataset.sgdel; s[k]=""; dirty("suppliers",s.id); saveLocal(); renderSignBox(s.id); syncSignUI(); toast("info", k==="stamp"?"Печать удалена":"Подпись удалена",""); });
let analyticsCustomer, analyticsRequest = 0;
function customerAnalytics(cid){
  analyticsCustomer = cid;
  $("#ca-name").textContent = cid ? (cus(cid).name || "") : "";
  caPeek(cid);
  if($("#cus-analytics").open) return renderCustomerAnalytics();
}
/* подпись в свёрнутом блоке: сколько купили в этом месяце — по журналу на устройстве */
function caPeek(cid){ const el=$("#ca-peek"); if(!el) return; if(!cid){ el.textContent=""; return; }
  const [a,b]=pfRange({per:"month"}), L=D.journal.filter(j=>j.customerId===cid && !isArch(j) && j.date>=a && j.date<=b), s=r2(L.reduce((x,j)=>x+(+j.sum||0),0));
  el.innerHTML = L.length ? `в этом месяце: <b>${L.length}</b> ${plural(L.length,["документ","документа","документов"])} · <b>${fm(s).replace(/,00$/,"")} ₽</b>` : `в этом месяце покупок нет`; }
let caAll=false, caSort="sum", caLast=null;
const CA_MON=["янв","фев","мар","апр","май","июн","июл","авг","сен","окт","ноя","дек"];
function drawCustomerAnalytics(docs, range){
  caLast={docs, range};
  const products = new Map(), byDay = {}; let total=0, hasSum=true, last="";
  for(const doc of docs){
    const ds = +doc.sum; if(!(ds>=0) || doc.sum==null || doc.sum==="") hasSum=false; else total+=ds;
    if(doc.date){ if(doc.date>last) last=doc.date; byDay[doc.date]=(byDay[doc.date]||0)+(ds||0); }
    const seen=new Set();
    for(const line of doc.snap.dr.lines){
      const qty = Number(line.qty);
      if(!line.productId || !Number.isFinite(qty) || qty <= 0) continue;
      const product = (doc.snap.prods || {})[line.productId] || {};
      const unit = String(product.unit || "").trim();
      const rt = pgRootId(line.productId), key = JSON.stringify([rt, unit]);   /* связанные названия одного товара — одной строкой */
      const item = products.get(key) || {name:(rt!==line.productId && prod(rt) ? prod(rt).name : "") || product.name || line.name || "Товар из документа", unit, qty:0, sum:0, n:0, priced:true};
      item.qty += qty; const pr=Number(line.price); if(Number.isFinite(pr) && line.price!=="" && line.price!=null) item.sum += r2(qty*pr); else item.priced=false;
      if(!seen.has(key)){ item.n++; seen.add(key); }
      products.set(key, item);
    }
  }
  const rows=[...products.values()], priced=rows.length && rows.every(r=>r.priced), lsum=r2(rows.reduce((a,r)=>a+r.sum,0));
  if(!rows.length){ $("#ca-result").innerHTML='<div class="ca-empty"><b>Покупок нет</b><span>За выбранный период документов у этого заказчика нет. Выберите другой период.</span></div>'; return; }
  const sorters={sum:(a,b)=>b.sum-a.sum||b.qty-a.qty, qty:(a,b)=>b.qty-a.qty, n:(a,b)=>b.n-a.n||b.sum-a.sum, name:(a,b)=>a.name.localeCompare(b.name,"ru")};
  if(!priced && caSort==="sum") caSort="qty";
  rows.sort(sorters[caSort]||sorters.name);
  const qf=new Intl.NumberFormat("ru-RU",{maximumFractionDigits:3}), rub=v=>fm(v).replace(/,00$/,""), top=caAll?rows:rows.slice(0,10), mx=Math.max(...rows.map(r=>priced?r.sum:r.qty))||1;
  /* график по дням (период до ~2 месяцев) или по месяцам */
  const days=Object.keys(byDay).sort(), lo=range[0]!=="0000"?range[0]:(days[0]||""), hi=range[1]!=="9999"?range[1]:(days[days.length-1]||""), span=lo&&hi?(new Date(hi)-new Date(lo))/864e5:0, byMonth=span>62;
  const B={}; days.forEach(d=>{ const k=byMonth?d.slice(0,7):d; B[k]=(B[k]||0)+byDay[d]; });
  const keys=[]; if(lo && hi && hasSum){ const c=new Date(lo+"T12:00:00"), e=new Date(hi+"T12:00:00"); if(byMonth){ c.setDate(1); while(c<=e && keys.length<60){ keys.push(jIso(c).slice(0,7)); c.setMonth(c.getMonth()+1); } } else { while(c<=e && keys.length<70){ keys.push(jIso(c)); c.setDate(c.getDate()+1); } } }
  const bm=Math.max(...keys.map(k=>B[k]||0))||1, lbl=k=>byMonth?CA_MON[+k.slice(5,7)-1]+(k.slice(0,4)!==String(new Date().getFullYear())?" "+k.slice(2,4):""):String(+k.slice(8,10));
  const chart = hasSum && keys.length>1 && days.length ? `<div class="ca-chart"><div class="ca-ch-h"><b>Покупки ${byMonth?"по месяцам":"по дням"}</b><small class="muted">наведите или нажмите на столбик</small></div>
      <div class="ca-cols" style="--n:${keys.length}">${keys.map((k,i)=>{ const v=B[k]||0; return `<div class="ca-col${v?"":" z"}" tabindex="${v?0:-1}" title="${byMonth?CA_MON[+k.slice(5,7)-1]+" "+k.slice(0,4):fd(k)}: ${v?rub(v)+" ₽":"нет покупок"}"><i style="--h:${(v/bm*100).toFixed(1)}%;--d:${Math.min(i*18,600)}ms"><em>${v?rub(v):""}</em></i><span>${keys.length<=16||i%Math.ceil(keys.length/12)===0?lbl(k):""}</span></div>`; }).join("")}</div></div>` : "";
  const avg = hasSum && docs.length ? r2(total/docs.length) : 0;
  const tiles = `<div class="ca-tiles">
      <div><small>Документов</small><b>${docs.length}</b></div>
      ${hasSum?`<div class="hi"><small>Сумма покупок</small><b>${rub(r2(total))} ₽</b></div><div><small>Средний чек</small><b>${rub(avg)} ₽</b></div>`:""}
      <div><small>Разных товаров</small><b>${rows.length}</b></div>
      ${last?`<div><small>Последняя поставка</small><b>${fd(last)}</b><span>${(()=>{ const d=daysSince(last); return d===0?"сегодня":d<0?"":dnum(d)+" назад"; })()}</span></div>`:""}
    </div>`;
  const th=(k,l,cls)=>`<th class="${cls||""}"><button type="button" class="ca-sort${caSort===k?" on":""}" data-casort="${k}">${l}${caSort===k?" ↓":""}</button></th>`;
  const table = `<div class="ca-tw"><div class="ca-ch-h"><b>Что покупает</b><small class="muted">${caAll||rows.length<=10?"все "+rows.length:"топ‑10 из "+rows.length}</small></div>
    <div class="tbl"><table class="ca-tab"><thead><tr><th class="ca-i">#</th>${th("name","Товар")}${th("qty","Купили","num")}${priced?th("sum","Сумма, ₽","num")+`<th class="num">Ср. цена</th><th class="ca-sh">Доля</th>`:""}${th("n","В документах","num")}</tr></thead>
    <tbody>${top.map((r,i)=>{ const share=priced&&lsum?r.sum/lsum*100:0; return `<tr style="--d:${Math.min(i*25,400)}ms"><td class="ca-i">${i+1}</td><td><b>${esc(r.name)}</b></td><td class="num">${qf.format(r.qty)} <small class="muted">${esc(r.unit||"")}</small></td>${priced?`<td class="num"><b>${rub(r.sum)}</b></td><td class="num muted">${r.qty?fm(r.sum/r.qty):"—"}</td><td class="ca-sh"><span class="ca-shb"><i style="--w:${(r.sum/mx*100).toFixed(1)}%"></i></span><small>${share.toFixed(share<1?1:0).replace(".",",")}%</small></td>`:""}<td class="num">${r.n} <small class="muted">из ${docs.length}</small></td></tr>`; }).join("")}</tbody></table></div>
    ${rows.length>10?`<div class="row"><button type="button" class="btn ghost sm" id="ca-more">${caAll?"Свернуть до топ‑10":"Показать все "+rows.length}</button></div>`:""}</div>`;
  $("#ca-result").innerHTML = tiles + chart + table + (hasSum?"":`<p class="muted" style="font-size:12.5px">Суммы появятся после обновления скрипта Google Таблицы.</p>`);
}
async function renderCustomerAnalytics(){
  const request = ++analyticsRequest, cid = analyticsCustomer;
  const status = $("#ca-status");
  const per = $("#ca-period").value;
  const custom = per === "custom";
  $("#ca-perseg").querySelectorAll("button").forEach(b=>{ const on=b.dataset.per===per; b.classList.toggle("on",on); b.setAttribute("aria-pressed",on); });
  $("#ca-from-label").hidden = $("#ca-to-label").hidden = !custom;
  const from = $("#ca-from").value, to = $("#ca-to").value;
  if(!cid){ $("#ca-result").textContent=""; status.textContent = "Выберите заказчика."; return; }
  if(custom && (!from || !to || from > to)){
    $("#ca-result").textContent=""; status.textContent = "Укажите обе даты. Дата начала должна быть не позже даты окончания.";
    return;
  }
  const range = pfRange({per,from,to}), [start,end] = range;
  const local = ()=>D.journal.filter(j=>j.customerId===cid && j.date>=start && j.date<=end &&
    !isArch(j) && Array.isArray(j.snap?.dr?.lines));
  const showLocal = message=>{ status.textContent = message; drawCustomerAnalytics(local(), range); };
  /* сразу показываем то, что есть на устройстве, потом уточняем по таблице */
  drawCustomerAnalytics(local(), range); $("#ca-result").classList.add("ca-load");
  const done = ()=>$("#ca-result").classList.remove("ca-load");
  if(!online()){ done(); showLocal("Показан журнал на этом устройстве. Для полной истории подключитесь к интернету."); return; }
  status.textContent = "Загружаем полную историю…";
  try{
    if(pend.journal.size) await flush();
    if(request !== analyticsRequest) return;
    if(pend.journal.size){ done(); showLocal("Показан журнал на этом устройстве. Для полной истории дождитесь сохранения документов."); return; }
    const response = await api({action:"customerAnalytics", customerId:cid, from:start, to:end});
    if(request !== analyticsRequest) return;
    if(pend.journal.size){ done(); showLocal("Документы изменились во время загрузки. Обновите отчёт после их сохранения."); return; }
    status.textContent = ""; done();
    /* старый скрипт не отдаёт даты и суммы — берём их из журнала на устройстве, если он полный */
    const docs=response.documents||[], loc=local();
    drawCustomerAnalytics(docs.length && docs[0].date==null && docs.length===loc.length ? loc : docs, range);
  }catch(e){
    if(request !== analyticsRequest) return;
    done();
    showLocal(e.message === "unknown action"
      ? "Показан журнал на этом устройстве. Для полной истории обновите скрипт Google Таблицы."
      : "Полная история недоступна. Показан журнал на этом устройстве.");
  }
}
