/* список цен заказчика: по страницам (10 / 20 / 50 / все), поиск и фильтр */
const PRV={cid:null, page:0, q:"", f:"all"};
const prSize = () => { const v=getPrefs().prSize; return v===0 ? 1e9 : [10,20,50].includes(v) ? v : 10; };
function pagerHtml(page, pages, total, from, n, size){
  if(!total) return "";
  const nums=[]; for(let i=0;i<pages;i++){ if(i===0||i===pages-1||Math.abs(i-page)<=1) nums.push(i); else if(nums[nums.length-1]!=="…") nums.push("…"); }
  return `<div class="pgnav">${pages>1?`<button type="button" class="pgb" data-pg="${page-1}"${page?"":" disabled"} aria-label="Предыдущая страница">‹</button>${nums.map(i=>i==="…"?`<span class="pgd">…</span>`:`<button type="button" class="pgb${i===page?" on":""}" data-pg="${i}" aria-label="Страница ${i+1}"${i===page?' aria-current="page"':""}>${i+1}</button>`).join("")}<button type="button" class="pgb" data-pg="${page+1}"${page<pages-1?"":" disabled"} aria-label="Следующая страница">›</button>`:""}</div>
    <span class="muted pgi">${from+1}–${from+n} из ${total}</span>
    <div class="pgsize" role="group" aria-label="Сколько показывать"><span class="muted">Показывать</span>${[[10,"10"],[20,"20"],[50,"50"],[0,"все"]].map(([v,l])=>`<button type="button" data-ps="${v}" class="${(v||1e9)===size?"on":""}">${l}</button>`).join("")}</div>`; }
function prRedraw(){ const t=$("#pr-tbl"); renderPrices(PRV.cid); if(t){ t.classList.remove("pgfade"); void t.offsetWidth; t.classList.add("pgfade"); } }
$("#pr-pager").addEventListener("click",e=>{ const b=e.target.closest("[data-pg],[data-ps]"); if(!b || b.disabled) return;
  if(b.dataset.ps!=null){ const p=getPrefs(); p.prSize=+b.dataset.ps; setPrefs(p,true); PRV.page=0; }
  else PRV.page=+b.dataset.pg;
  prRedraw(); if(b.dataset.pg!=null){ const t=$("#pr-tbl"); if(t && t.getBoundingClientRect().top<0) t.scrollIntoView({behavior:"smooth", block:"start"}); } });
let prQT=null; $("#pr-q").addEventListener("input",e=>{ clearTimeout(prQT); prQT=setTimeout(()=>{ PRV.q=e.target.value; PRV.page=0; prRedraw(); },180); });
$("#pr-f").addEventListener("change",e=>{ PRV.f=e.target.value; PRV.page=0; prRedraw(); });
function renderPrices(cid){
  const c=cus(cid); $("#pr-name").textContent=$("#im-name").textContent=c.name?"— "+c.name:""; plBox(c);
  if(!cid){ $("#pr-body").innerHTML=""; $("#pr-pager").innerHTML=""; return; }
  const pl=D.prices[cid]=D.prices[cid]||{};
  $("#pr-copyfrom").innerHTML=`<option value="">Скопировать цены другого заказчика…</option>`+opts(D.customers.filter(x=>x.id!==cid));
  if(PRV.cid!==cid){ PRV.cid=cid; PRV.page=0; PRV.q=""; $("#pr-q").value=""; }
  const q=norm(PRV.q||""), has=p=>pl[p.id]!=null&&pl[p.id]!=="", all=D.products.filter(p=>(!q||norm(p.name).includes(q)) && (PRV.f==="all"||(PRV.f==="has")===has(p)) && prCatOk(p)); prCatChips(cid);
  const size=prSize(), pages=Math.max(1,Math.ceil(all.length/size)); if(PRV.page>=pages) PRV.page=pages-1; const from=PRV.page*size, list=all.slice(from, from+size);
  $("#pr-f").value=PRV.f; $("#pr-cnt").textContent=D.products.filter(has).length+" с ценой из "+D.products.length;
  $("#pr-pager").innerHTML=pagerHtml(PRV.page, pages, all.length, from, list.length, size);
  $("#pr-body").innerHTML=(list.length?"":`<tr><td colspan="5" class="muted" style="padding:12px 6px">Ничего не найдено.</td></tr>`)+list.map(p=>{ const sp=specOf(cid,p.id); return `<tr><td>${esc(p.name)}</td><td>${esc(p.unit)}</td><td class="num">${fm(p.price)}</td><td><input data-p="${p.id}" inputmode="decimal" placeholder="—" value="${pl[p.id]!=null?esc(pl[p.id]):""}"></td>
    <td><input data-s="spec" data-pid="${p.id}" value="${esc(sp.spec||"")}"></td></tr>`; }).join("");   /* ID СТЕ и артикул оферты нигде не используются — не показываем (в таблице остаются) */
  $("#pr-body").oninput=e=>{
    if(e.target.dataset.s){ const pid=e.target.dataset.pid, m=D.specs[cid]=D.specs[cid]||{}, x=m[pid]=m[pid]||{}; x[e.target.dataset.s]=e.target.value.trim(); dirtySpec(cid,pid); return; }
    const v=num(e.target.value), p=e.target.dataset.p; if(v==="") delete pl[p]; else pl[p]=v; dirtyPrice(cid,p); };
  $("#pp-name").textContent=c.name?"— "+c.name:""; ppRows=[]; $("#pp-wrap").hidden=$("#pp-act").hidden=true; $("#pp-msg").textContent="";
  $("#pr-copy").onclick=()=>{ const f=$("#pr-copyfrom").value; if(!f) return; const src=D.prices[f]||{};
    Object.keys(pl).forEach(p=>{ if(!(p in src)){ delete pl[p]; dirtyPrice(cid,p); } }); Object.keys(src).forEach(p=>{ pl[p]=src[p]; dirtyPrice(cid,p); }); renderPrices(cid); };
}

/* ---------- выгрузка спецификации из Портала поставщиков ---------- */
let ppRows=[];
function loadXLSX(){ return window.XLSX ? Promise.resolve(window.XLSX) : new Promise((ok,bad)=>{ const sc=document.createElement("script");
  sc.src="https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js"; sc.onload=()=>ok(window.XLSX); sc.onerror=()=>bad(new Error("не загрузилась библиотека чтения Excel")); document.head.appendChild(sc); }); }
const stem = w => w.length>5 ? w.slice(0,5) : w;
const toks = s => norm(s).replace(/[^a-zа-я0-9 ]/g," ").split(" ").filter(w=>w.length>=3).map(stem);
function guessProduct(cid, r, taken){
  const t=new Set(toks(r.spgz+" "+r.ste)); let best=null, bs=0;
  D.products.forEach(p=>{ if(taken.has(p.id)) return; const pt=toks(p.name); let sc=pt.filter(w=>t.has(w)).length/Math.max(pt.length,1);
    const cp=+custPrice(cid,p.id); if(r.price && cp && Math.abs(cp-r.price)<0.006) sc+=3;
    if(sc>bs){ bs=sc; best=p; } });
  return bs>=3 || bs>=0.75 ? best.id : "";
}
function parsePortalSheet(rows){
  const hi=rows.findIndex(r=>r.some(c=>/артикул/i.test(c)) && r.some(c=>/спецификац|сте/i.test(c)));
  if(hi<0) return [];
  const h=rows[hi].map(x=>String(x||"").trim()), f=(...res)=>{ for(const re of res){ const i=h.findIndex(x=>re.test(x)); if(i>=0) return i; } return -1; };
  const iSpec=f(/^ид\s*спецификации/i,/идентификатор\s*позиции/i,/ид.*спецификац/i),
        iSpgz=f(/наименование\s*закупочн/i,/^наименование$/i,/спгз/i), iSteN=f(/наименование\s*сте/i),
        iSte=f(/id\s*поставочн/i,/^id\s*сте/i,/идентификатор\s*сте/i), iArt=f(/артикул/i),
        iPrice=f(/цена.*без\s*ндс/i,/цена/i), iQty=f(/количеств/i), iSum=f(/сумма\s*без\s*ндс/i,/^сумма$/i);
  return rows.slice(hi+1).map(r=>{ const g=i=>i>=0?String(r[i]==null?"":r[i]).trim():""; const pr=money(g(iPrice)), q=money(g(iQty)), sm=money(g(iSum));
    return {spec:g(iSpec), spgz:g(iSpgz), ste:g(iSteN), steId:g(iSte), art:g(iArt), price: isFinite(pr)&&pr>0 ? pr : (q>0&&isFinite(sm)?sm/q:0)}; })
    .filter(x=>x.spec);
}
$("#pp-file").onchange=async e=>{
  const f=e.target.files[0]; e.target.value=""; if(!f) return; const cid=editorSel.customers; if(!cid) return;
  $("#pp-msg").textContent="Читаю файл…";
  try{
    if(/\.(xml|txt)$/i.test(f.name)){ const n=await learnFromSentXml(cid, f); $("#pp-msg").textContent=n.msg; renderPrices(cid); $("#pp-msg").textContent=n.msg; return; }
    let rows;
    if(/\.csv$/i.test(f.name)){ rows=(await f.text()).split(/\r?\n/).map(l=>l.split(/;|\t/)); }
    else { const X=await loadXLSX(); const wb=X.read(await f.arrayBuffer(),{type:"array"}); rows=[]; wb.SheetNames.forEach(n=>{ rows=rows.concat(X.utils.sheet_to_json(wb.Sheets[n],{header:1,raw:true,defval:""})); }); }
    ppRows=parsePortalSheet(rows);
    if(!ppRows.length){ $("#pp-msg").textContent="Не нашёл в файле колонок с артикулом и СТЕ. Это точно выгрузка «Сведения о спецификациях»?"; return; }
    const taken=new Set(); ppRows.forEach(r=>{ r.pid=guessProduct(cid,r,taken); if(r.pid) taken.add(r.pid); });
    const po=sel=>`<option value="">— не сопоставлять —</option>`+D.products.map(p=>`<option value="${p.id}"${p.id===sel?" selected":""}>${esc(p.name)}</option>`).join("");
    $("#pp-body").innerHTML=ppRows.map((r,i)=>`<tr><td>${esc(r.spgz)}${r.ste&&r.ste!==r.spgz?`<br><span class="muted">${esc(r.ste)}</span>`:""}</td><td>${esc(r.spec)}</td><td>${esc(r.steId)}</td><td>${esc(r.art)}</td><td class="num">${r.price?fm(r.price):""}</td><td><select data-i="${i}" style="${r.pid?"":"border-color:var(--err)"}">${po(r.pid)}</select></td></tr>`).join("");
    $("#pp-wrap").hidden=$("#pp-act").hidden=false;
    const n=ppRows.filter(r=>r.pid).length, noArt=ppRows.filter(r=>!r.art).length;
    $("#pp-msg").textContent="Позиций в файле: "+ppRows.length+", сопоставлено автоматически: "+n+". Проверьте колонку «Ваш товар» и сохраните.";
  }catch(err){ $("#pp-msg").textContent="Не удалось прочитать файл: "+err.message; }
};
async function learnFromSentXml(cid, f){
  const buf=await f.arrayBuffer(); let txt=new TextDecoder("utf-8").decode(buf);
  if(/encoding="windows-1251"/i.test(txt.slice(0,200))) txt=new TextDecoder("windows-1251").decode(buf);
  txt=txt.replace(/^[^<]*/,"");
  const doc=new DOMParser().parseFromString(txt,"application/xml"); if(doc.getElementsByTagName("parsererror").length) return {msg:"Файл не читается как XML."};
  const m=D.specs[cid]=D.specs[cid]||{}; let found=0, learned=0, unknown=0;
  [...doc.getElementsByTagName("ИдСпецификации")].forEach(el=>{ const par=el.parentNode, sp=el.textContent.trim(); const steEl=[...par.children].find(x=>x.tagName==="ИдСТЕ"); if(!steEl) return; found++;
    const ste=steEl.textContent.trim(); const pid=Object.keys(m).find(k=>m[k].spec===sp); if(!pid){ unknown++; return; }
    if(m[pid].ste!==ste){ m[pid].ste=ste; dirtySpec(cid,pid); learned++; } });
  if(!found) return {msg:"В файле не нашлось позиций с ИдСпецификации и ИдСТЕ. Загрузите XML документа, отправленного через Портал."};
  return {msg:"Из документа: позиций "+found+", записано новых ID СТЕ — "+learned+(unknown?", не найдено в сопоставлении — "+unknown+" (сначала загрузите выгрузку спецификации .xlsx)":"")+"."};
}
$("#pp-body").addEventListener("change",e=>{ const i=e.target.dataset.i; if(i!=null) ppRows[+i].pid=e.target.value; });
$("#pp-save").onclick=()=>{ const cid=editorSel.customers; const m=D.specs[cid]=D.specs[cid]||{}; let n=0;
  const specs=new Set(ppRows.filter(r=>r.pid).map(r=>r.spec));
  Object.keys(m).forEach(pid=>{ if(specs.has(m[pid].spec) && !ppRows.some(r=>r.pid===pid&&r.spec===m[pid].spec)){ delete m[pid]; dirtySpec(cid,pid); } });
  const pl=D.prices[cid]=D.prices[cid]||{}; let np=0;
  ppRows.forEach(r=>{ if(!r.pid) return; const old=m[r.pid]||{}; m[r.pid]={spec:r.spec, ste:r.steId||(old.spec===r.spec?old.ste:"")||"", art:r.art||old.art||""}; dirtySpec(cid,r.pid); n++;
    if(r.price){ const ex=String(+r.price.toFixed(11)); if(pl[r.pid]!==ex){ pl[r.pid]=ex; dirtyPrice(cid,r.pid); np++; } } });
  renderPrices(cid); $("#pp-msg").textContent="Сохранено: "+n+" позиций. Цены заказчика приведены к точным ценам спецификации ("+np+" поз.), суммы в документах совпадут с Порталом до копейки."; };

/* ---------- импорт прайса ---------- */
const norm = s => String(s||"").toLowerCase().replace(/ё/g,"е").replace(/\s+/g," ").trim();
const money = s => { let t=String(s==null?"":s).replace(/руб\.?|₽|р\./gi,"").replace(/[\s\u00a0]/g,""); if(/,\d{1,2}$/.test(t)) t=t.replace(/\./g,"").replace(",","."); else t=t.replace(/,/g,""); const v=parseFloat(t); return isFinite(v)?v:NaN; };
function parseTable(text){
  let rows=text.replace(/\r/g,"").split("\n").filter(r=>r.trim()).map(r=>r.split("\t"));
  if(rows.length && rows.every(r=>r.length===1)) rows=rows.map(r=>r[0].split(";"));
  const hi=rows.findIndex(r=>r.some(c=>/товар|наимен/i.test(c)) && r.some(c=>/цена/i.test(c)));
  let iN=0, iU=1, iP=-1, iC=-1, body=rows;
  if(hi>=0){ const h=rows[hi].map(x=>x.trim());
    const pick=(...res)=>{ for(const re of res){ const i=h.findIndex(x=>re.test(x)); if(i>=0) return i; } return -1; };
    iN=pick(/^товар/i,/наименование товара/i,/^наимен/i,/товар/i); iU=pick(/^ед/i); iP=pick(/цена контракта/i,/^цена(?!.*закуп)/i,/цена(?!.*закуп)/i); iC=pick(/^код|артикул/i);
    body=rows.slice(hi+1); }
  return body.map(r=>{ const price = iP>=0 ? money(r[iP]) : [...r].reverse().map(money).find(v=>isFinite(v));
    return {name:(r[iN]||"").trim(), unit:(iU>=0?(r[iU]||""):"").trim().toLowerCase().replace(/\.$/,""), price, code:iC>=0?(r[iC]||"").trim():""}; })
    .filter(x=>x.name && isFinite(x.price) && !/^итого/i.test(x.name));
}
function importRows(cid, items){
  const pl=D.prices[cid]=D.prices[cid]||{}; let added=0, priced=0;
  items.forEach(it=>{
    let p=D.products.find(x=>norm(x.name)===norm(it.name));
    if(!p){ p={id:uid(), name:it.name, code:it.code||"", unit:UNITS[it.unit]?it.unit:(/шт/.test(it.unit)?"шт":"кг"), country:"", price:String(it.price)}; D.products.push(p); dirty("products",p.id); added++; }
    else if(it.code && !p.code){ p.code=it.code; dirty("products",p.id); }
    pl[p.id]=String(it.price); dirtyPrice(cid,p.id); priced++;
  });
  return {added, priced};
}
$("#im-go").onclick=()=>{
  const cid=editorSel.customers; if(!cid){ $("#im-msg").textContent="Сначала выберите заказчика."; return; }
  const items=parseTable($("#im-text").value);
  if(!items.length){ $("#im-msg").textContent="Не нашёл строк с названием и ценой. Скопируйте таблицу вместе с заголовком."; return; }
  const r=importRows(cid, items); $("#im-text").value="";
  $("#im-msg").textContent="Готово: цены записаны для "+r.priced+" позиций, новых товаров в номенклатуре — "+r.added+".";
  renderPrices(cid);
};

