/* ФГБУ «НМИЦ гематологии» — контракт № 0373100056625001682_46047 (44-ФЗ, бакалея, лот 1): все 16 позиций спецификации.
   Цены за единицу — из обоснования НМЦК (Приложение 2), контракт заключён по ним: сумма цен единиц 11 965,74 ₽, цены сходятся с заявками.
   Добавляются только недостающие позиции; уже заведённые цены и названия не трогаются. */
const NMIC_SPEC=[
  ["Ваниль обработанная",1587.52,["Ваниль","Ванильный порошок","Ванилин"]],
  ["Дрожжи хлебопекарные сушеные",595.32,["Дрожжи","Дрожжи сухие","Дрожжи сушеные"]],
  ["Казеин пищевой",2565.83,["Казеин"]],
  ["Какао-порошок",1091.42,["Какао","Какао порошок"]],
  ["Кофейный напиток",377.04,["Коф. напиток","Кофе напиток","Напиток кофейный"]],
  ["Крахмалы, кроме модифицированных",114.10,["Крахмал","Крахмал картофельный"]],
  ["Лист лавровый сушеный",1298.59,["Лавровый лист","Лист лавровый"]],
  ["Перец обработанный (душистый, горошек)",2182.84,["Перец душистый","Перец душистый горошек","Перец обработанный душистый"]],
  ["Перец обработанный (черный, горошек)",907.86,["Перец черный","Перец черный горошек","Перец обработанный черный"]],
  ["Ягоды сушеные",327.43,["Шиповник","Шиповник сушеный","Шиповника плоды сушеные","Ягоды сушеные (шиповник)"]],
  ["Горох шлифованный",99.22,["Горох","Горох колотый"]],
  ["Изделия макаронные (вермишель)",104.18,["Вермишель","Изделия макаронные вермишель"]],
  ["Изделия макаронные (лапша)",104.18,["Лапша","Изделия макаронные лапша"]],
  ["Изделия макаронные (макароны фигурные)",104.18,["Макароны фигурные","Изделия макаронные фигурные","Спирали"]],
  ["Рис круглозерновой",133.95,["Рис кр","Рис круглый","Рис (круглозерновой)"]],
  ["Рис пропаренный",178.60,["Рис пр","Рис (пропаренный)"]],
  ["Фасоль продовольственная",297.66,["Фасоль"]]];
function patchNmic(){
  const c=D.customers.find(x=>x.inn==="7714061756") || D.customers.find(x=>/гематолог/i.test(x.name||"")); if(!c) return 0;
  const pl=D.prices[c.id]=D.prices[c.id]||{}, has=pid=>pl[pid]!=null && pl[pid]!=="";
  const names=p=>[p.name, ...aliasesOf(p)].map(norm);
  let n=0;
  NMIC_SPEC.forEach(([name,price,al])=>{
    const want=[name, ...al].map(norm);
    if(Object.keys(pl).some(pid=>{ const p=prod(pid); return p && has(pid) && names(p).some(x=>want.includes(x)); })) return;   /* уже есть в прайсе НМИЦ */
    let p=D.products.find(x=>norm(x.name)===norm(name) && (x.unit||"кг")==="кг") || D.products.find(x=>(x.unit||"кг")==="кг" && aliasesOf(x).some(a=>norm(a)===norm(name)));
    if(!p){ p={id:uid(), name, code:"", unit:"кг", country:"643", price:String(price)}; D.products.push(p); }
    const A=aliasesOf(p); al.forEach(x=>{ if(!A.some(y=>norm(y)===norm(x)) && norm(x)!==norm(p.name)) A.push(x); }); p.aliases=JSON.stringify(A.slice(-20));
    dirty("products",p.id); pl[p.id]=String(price); dirtyPrice(c.id,p.id); n++;
  });
  if(n) logEv("Справочники","НМИЦ гематологии: добавлены позиции спецификации контракта — "+n);
  return n;
}
