  spec.forEach(r=>{ const q=+String(r.qty).replace(",","."); if(r.pid && q>0 && (cumQ[r.pid]||0)>q+0.0005) W.push({l:0, t:"«"+r.name+"»: с начала договора поставлено "+aktQ(cumQ[r.pid])+" "+(r.unit||"")+", а по договору "+aktQ(q)+" — превышение."}); });
